mapper.select:
SELECT a.asgn_id, a.dev_id, d.dev_nm,
  coalesce(s.emp_se_cd,d.emp_se_cd) AS emp_se_cd,
  a.prj_id, p.prj_nm, p.cntrct_ty_cd, a.end_dt
FROM asgn.asgn a
JOIN prj.prj p ON p.prj_id=a.prj_id
JOIN mst.dev d ON d.dev_id=a.dev_id
LEFT JOIN cst.mth_cst s ON s.dev_id=a.dev_id AND s.cst_ym=#{month}
WHERE p.prj_stts_cd='RUN' AND p.cntrct_ty_cd IN ('MO','DP')
  AND p.free_sprt_yn='N' AND a.asgn_se_cd!='FREE'
  AND a.asgn_stts_cd='ACTIVE' AND a.bgn_dt <= #{today}
  AND a.end_dt >= #{today} AND a.end_dt <= #{through}
AND coalesce(s.emp_se_cd,d.emp_se_cd)=#{empType}
AND a.prj_id=#{projectId}
ORDER BY a.end_dt,a.asgn_id
